    def _check_buffer(self) -> None:
        """Check if the buffer should be flushed."""
        if not self._buffer:
            return

        if self.overflowing:
            # Flush the buffer if it's overflowing.
            try:
                # We use a local variable for the write method to avoid
                # repeated attribute lookups in the loop.
                write = self.file.write
                for text in self._buffer:
                    try:
                        write(text)
                    except BrokenPipeError:
                        sys.exit(0)
            except BrokenPipeError:
                sys.exit(0)

            del self._buffer[:]
            return

        if self.file.isatty():
            # If the output is a TTY, we flush the buffer on every print.
            try:
                write = self.file.write
                for text in self._buffer:
                    try:
                        write(text)
                    except BrokenPipeError:
